@import "tailwindcss";

@theme {
  --color-cream: #faf5e9;
  --color-cream-deep: #f1e6d0;
  --color-parchment: #e9dbbd;
  --color-espresso: #2b2013;
  --color-espresso-soft: #43331f;
  --color-espresso-muted: #6b5638;
  --color-copper: #b5672f;
  --color-copper-deep: #8a4c22;
  --color-copper-light: #dd9a5c;
  --color-tea: #4c6641;
  --color-tea-deep: #34472c;
  --color-tea-light: #7f9a6c;

  --font-display: Georgia, "Iowan Old Style", "Palatino Linotype", "Book Antiqua", serif;
  --font-body: ui-sans-serif, -apple-system, "Segoe UI", Inter, sans-serif;
}

:root {
  color-scheme: light dark;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 4.5rem;
}

body {
  font-family: var(--font-body);
}

::selection {
  background-color: var(--color-copper-light);
  color: var(--color-espresso);
}

:focus-visible {
  outline: 2px solid var(--color-copper);
  outline-offset: 3px;
  border-radius: 2px;
}

@keyframes steam-rise {
  0% {
    transform: translateY(0) scaleX(1);
    opacity: 0;
  }
  20% {
    opacity: 0.55;
  }
  100% {
    transform: translateY(-34px) scaleX(1.4);
    opacity: 0;
  }
}

.animate-steam {
  animation: steam-rise 3.6s ease-in-out infinite;
}

