type Props = {
  className?: string;
};

/** The Copperleaf brand mark: a single veined leaf. */
export function LeafMark({ className = "" }: Props) {
  return (
    <svg viewBox="0 0 48 48" fill="none" className={className} aria-hidden="true">
      <path
        d="M24 4C13 10 6 19 6 28c0 8.5 7.5 15 16 16 3-9 2-19-2-27"
        stroke="currentColor"
        strokeWidth="2.2"
        strokeLinecap="round"
      />
      <path
        d="M24 4c11 6 18 15 18 24 0 8.5-7.5 15-16 16"
        stroke="currentColor"
        strokeWidth="2.2"
        strokeLinecap="round"
      />
      <path d="M24 12v30" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" opacity="0.7" />
      <path d="M24 20c-4 1-7 3-9 6M24 20c4 1 7 3 9 6M24 28c-3 1-5 2.5-6.5 5M24 28c3 1 5 2.5 6.5 5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" opacity="0.55" />
    </svg>
  );
}

/** Large watermark vein pattern used behind hero copy. */
export function LeafVeinWatermark({ className = "" }: Props) {
  return (
    <svg viewBox="0 0 400 400" fill="none" className={className} aria-hidden="true">
      <path
        d="M200 20C90 70 30 150 30 220c0 90 70 150 170 160 30-95 20-200-20-280"
        stroke="currentColor"
        strokeWidth="1.5"
      />
      <path
        d="M200 20c110 50 170 130 170 200 0 90-70 150-170 160"
        stroke="currentColor"
        strokeWidth="1.5"
      />
      <path d="M200 55v300" stroke="currentColor" strokeWidth="1" opacity="0.6" />
      {Array.from({ length: 9 }).map((_, i) => {
        const y = 70 + i * 30;
        const spread = 30 + i * 4;
        return (
          <path
            key={i}
            d={`M200 ${y}c-${spread} 8-${spread + 14} 18-${spread + 22} 32M200 ${y}c${spread} 8 ${spread + 14} 18 ${spread + 22} 32`}
            stroke="currentColor"
            strokeWidth="0.8"
            opacity="0.45"
          />
        );
      })}
    </svg>
  );
}

