type TeaItem = {
  name: string;
  description: string;
  price: string;
};

type TeaCategory = {
  title: string;
  note: string;
  items: TeaItem[];
};

const categories: TeaCategory[] = [
  {
    title: "Black Teas",
    note: "Bold and malty, best with milk",
    items: [
      { name: "Copperleaf Breakfast", description: "Assam & Ceylon blend, brisk and full-bodied", price: "$4.50" },
      { name: "Earl of Cornwall", description: "Black tea with cold-pressed bergamot and cornflower", price: "$4.75" },
      { name: "Smoked Lapsang", description: "Pinewood-smoked leaves from the Wuyi hills", price: "$5.00" },
      { name: "Spiced Chai", description: "Cinnamon, cardamom, clove, and black pepper, steeped in milk", price: "$5.25" },
    ],
  },
  {
    title: "Green & White Teas",
    note: "Light, grassy, gently sweet",
    items: [
      { name: "Jade Dew Sencha", description: "Steamed Japanese green with a bright, vegetal cup", price: "$4.75" },
      { name: "Jasmine Pearl", description: "Hand-rolled green pearls scented with night jasmine", price: "$5.25" },
      { name: "Silver Needle White", description: "Downy young buds, delicate and faintly honeyed", price: "$5.75" },
    ],
  },
  {
    title: "Herbal & Tisanes",
    note: "Caffeine-free, by the pot",
    items: [
      { name: "Chamomile Honey Blossom", description: "Whole chamomile flowers with a touch of dried honey", price: "$4.50" },
      { name: "Peppermint Garden", description: "Cooling peppermint leaf, cut and sifted", price: "$4.25" },
      { name: "Hibiscus Ember", description: "Tart hibiscus, rosehip, and orange peel, served iced or hot", price: "$4.75" },
    ],
  },
  {
    title: "Copperleaf Specialties",
    note: "House blends, made in-room",
    items: [
      { name: "Copperleaf Signature", description: "Rooibos, cinnamon bark, and orange peel — our founding blend", price: "$5.50" },
      { name: "Golden Turmeric Latte", description: "Turmeric, ginger, and black pepper steamed with oat milk", price: "$5.75" },
      { name: "Iced Peach Oolong", description: "Oolong cold-steeped overnight with white peach", price: "$5.50" },
    ],
  },
];

export function TeaMenu() {
  return (
    <section id="menu" className="bg-cream-deep dark:bg-espresso-soft">
      <div className="mx-auto max-w-5xl px-6 py-20">
        <div className="max-w-xl">
          <span className="text-xs font-medium uppercase tracking-[0.2em] text-copper-deep dark:text-copper-light">
            The Menu
          </span>
          <h2 className="mt-3 font-display text-3xl font-semibold text-espresso sm:text-4xl dark:text-cream">
            Tea, by the pot
          </h2>
          <p className="mt-3 text-espresso-muted dark:text-cream-deep">
            Every pot is steeped to order and served with a timer, so nothing
            goes bitter. Ask your server for a stronger or lighter steep — we're
            happy to adjust.
          </p>
        </div>

        <div className="mt-12 grid gap-10 sm:grid-cols-2">
          {categories.map((category) => (
            <div key={category.title}>
              <div className="flex items-baseline justify-between border-b border-copper/30 pb-2">
                <h3 className="font-display text-xl font-semibold text-espresso dark:text-cream">
                  {category.title}
                </h3>
                <span className="text-xs text-espresso-muted dark:text-cream-deep/80">{category.note}</span>
              </div>
              <ul className="mt-4 space-y-4">
                {category.items.map((item) => (
                  <li key={item.name} className="flex items-start justify-between gap-4">
                    <div>
                      <p className="font-medium text-espresso dark:text-cream">{item.name}</p>
                      <p className="text-sm text-espresso-muted dark:text-cream-deep/80">{item.description}</p>
                    </div>
                    <span className="shrink-0 whitespace-nowrap font-display text-copper-deep dark:text-copper-light">
                      {item.price}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
